\title{Shifted Hankel Moment Certificates for Detecting\\Negative Partial-Transpose Spectra}
\author{Aristotle}
\date{July 16, 2026}
\begin{document}
\maketitle

\begin{abstract}
Moment-based relaxations of the positive-partial-transpose condition replace full spectral reconstruction by positivity tests on finite Hankel matrices assembled from power moments. For a finite weighted real spectrum with $p_k=\sum_jw_jx_j^k$, define $H_m=(p_{a+b+1})_{0\leq a,b<m}$. We prove the exact identity
\[
c^{\mathsf T}H_mc=\sum_jw_jx_jf_c(x_j)^2,
\qquad f_c(t)=\sum_{a=0}^{m-1}c_at^a.
\]
Consequently, nonnegative weights and nodes make every $H_m$ positive semidefinite. The hierarchy is nested, and its first nonlinear member is $p_2^2\leq p_1p_3$. A strict reverse inequality certifies a negative node. If exact moments bounded by $B$ violate this inequality with margin $\delta$, uniform measurement error $\varepsilon$ preserves the violation whenever $2(2B\varepsilon+\varepsilon^2)<\delta$. A Gram factorization yields practical testing and witness-extraction algorithms. These deterministic results isolate the finite spectral mechanism relevant to random induced bipartite states without asserting ensemble-specific asymptotic thresholds.
\end{abstract}

\section{Introduction}
Let $\rho$ be a density operator on a bipartite Hilbert space and let $\rho^\Gamma$ denote partial transposition in one subsystem. Every separable state satisfies $\rho^\Gamma\succeq0$. Thus a negative eigenvalue of $\rho^\Gamma$ certifies entanglement.

Full diagonalization can be poorly matched to experiment, whereas traces of low powers may be accessible. This motivates finite criteria built from moments of the partial-transpose spectrum. The underlying support question is classical: which moment sequences can arise from a nonnegative measure supported on $[0,\infty)$? For every real polynomial $f$, such a measure obeys $\sum_jw_jx_jf(x_j)^2\geq0$. Restricting the degree of $f$ produces finite shifted Hankel matrices.

We develop this algebra for arbitrary finite real spectra with nonnegative weights. The results separate model-independent spectral geometry from the random-matrix asymptotics required to establish typical thresholds for induced states.

\section{Definitions and PPT interpretation}
Let $J$ be finite, with nodes $x_j\in\mathbb R$ and weights $w_j\in\mathbb R$.

\begin{definition}[Power moments]
For $k\geq0$, define
\[
p_k=\sum_{j\in J}w_jx_j^k.
\]
No probability normalization is required.
\end{definition}

\begin{definition}[Shifted Hankel matrix]
For $m\geq1$, define
\[
H_m=(p_{a+b+1})_{0\leq a,b<m}.
\]
In particular,
\[
H_1=(p_1),\qquad H_2=\begin{pmatrix}p_1&p_2\\p_2&p_3\end{pmatrix}.
\]
Level $m$ uses moments through $p_{2m-1}$.
\end{definition}

\begin{definition}[Polynomial probe]
For $c=(c_0,\ldots,c_{m-1})^{\mathsf T}$, let
\[
f_c(t)=\sum_{a=0}^{m-1}c_at^a.
\]
\end{definition}

For a Hermitian matrix $A$ with eigenvalues $x_j$ and unit multiplicity weights, $p_k=\Tr(A^k)$. If $A=\rho^\Gamma$, node nonnegativity is precisely the PPT condition. Hence a violated necessary condition for nonnegative nodes certifies non-PPT behavior. Satisfaction at a finite level is generally inconclusive.

\section{Quadratic identity and Gram geometry}
\begin{theorem}[Shifted-Hankel sum-of-squares identity]
For every finite weighted real spectrum, every $m\geq1$, and every $c\in\mathbb R^m$,
\[
c^{\mathsf T}H_mc=\sum_{j\in J}w_jx_jf_c(x_j)^2.
\]
\end{theorem}
\begin{proof}
Expanding and reordering finite sums gives
\begin{align*}
c^{\mathsf T}H_mc
&=\sum_{a,b=0}^{m-1}c_ac_bp_{a+b+1}\\
&=\sum_jw_jx_j\left(\sum_ac_ax_j^a\right)
                 \left(\sum_bc_bx_j^b\right),
\end{align*}
which is the claimed expression.
\end{proof}

\begin{theorem}[Positive shifted moments]
If $w_j\geq0$ and $x_j\geq0$ for all $j$, then $H_m$ is positive semidefinite for every $m\geq1$.
\end{theorem}
\begin{proof}
Every summand $w_jx_jf_c(x_j)^2$ in the preceding identity is nonnegative.
\end{proof}

\begin{theorem}[Gram representation]
Under the same sign assumptions, define $v_a\in\mathbb R^J$ by
\[
v_a(j)=\sqrt{w_jx_j}\,x_j^a.
\]
Then $(H_m)_{ab}=\langle v_a,v_b\rangle$.
\end{theorem}
\begin{proof}
The product $v_a(j)v_b(j)$ equals $w_jx_j^{a+b+1}$; summation gives $p_{a+b+1}$.
\end{proof}

Thus $H_m=V^{\mathsf T}V$ for the feature matrix $V$. The shift by one inserts the factor $x_j$ and makes $H_m$ a localizing matrix for the support constraint $x\geq0$.

\section{Nesting}
\begin{theorem}[Nesting Theorem]
If $H_{m+1}$ is positive semidefinite, then $H_m$ is positive semidefinite.
\end{theorem}
\begin{proof}
Extend $c\in\mathbb R^m$ to $\widetilde c=(c_0,\ldots,c_{m-1},0)$. Then
\[
\widetilde c^{\mathsf T}H_{m+1}\widetilde c=c^{\mathsf T}H_mc.
\]
The left side is nonnegative by hypothesis.
\end{proof}

\begin{corollary}[Persistence of violations]
If $H_m$ is not positive semidefinite, then $H_r$ is not positive semidefinite for every $r\geq m$.
\end{corollary}
\begin{proof}
Otherwise repeated nesting would imply positivity of $H_m$.
\end{proof}

Nesting does not by itself prove strict improvement: establishing that each added degree detects new spectra or changes an ensemble threshold requires additional analysis.

\section{The first nonlinear certificate}
\begin{theorem}[First nonlinear moment inequality]
If $w_j\geq0$ and $x_j\geq0$ for all $j$, then
\[
p_2^2\leq p_1p_3.
\]
\end{theorem}
\begin{proof}
Set $u_j=\sqrt{w_jx_j}$ and $v_j=\sqrt{w_jx_j}\,x_j$. Then
$\langle u,u\rangle=p_1$, $\langle u,v\rangle=p_2$, and
$\langle v,v\rangle=p_3$. Cauchy--Schwarz proves the inequality. Equivalently, $\det H_2\geq0$.
\end{proof}

\begin{theorem}[Negative-node certificate]
Suppose $w_j\geq0$ for every $j$. If
\[
p_1p_3<p_2^2,
\]
then $x_j<0$ for at least one $j$.
\end{theorem}
\begin{proof}
If all nodes were nonnegative, the preceding theorem would give the opposite weak inequality.
\end{proof}

\begin{example}
Unit weights on $1,2,3$ give $(p_1,p_2,p_3)=(6,14,36)$ and $196\leq216$. Unit weights on $-1,2,3$ give $(4,14,34)$ and $196>136$, certifying a negative node. The converse fails: nodes $-0.01,1,2$ with weights $0.01,1,1$ give $p_2^2-p_1p_3\approx-1.99909$, so this level does not detect their negative component.
\end{example}

\section{Robustness under approximate moments}
Write
\[
D(p)=p_2^2-p_1p_3,
\qquad D(q)=q_2^2-q_1q_3.
\]

\begin{theorem}[Deterministic stability]
Assume $|p_i|\leq B$ and $|q_i-p_i|\leq\varepsilon$ for $i=1,2,3$. If $D(p)\geq\delta$ and
\[
2(2B\varepsilon+\varepsilon^2)<\delta,
\]
then $D(q)>0$, or equivalently $q_1q_3<q_2^2$.
\end{theorem}
\begin{proof}
Let $e_i=q_i-p_i$. Then
\[
q_1q_3-p_1p_3=p_1e_3+p_3e_1+e_1e_3,
\]
so its absolute value is at most $2B\varepsilon+\varepsilon^2$. Likewise,
\[
q_2^2-p_2^2=2p_2e_2+e_2^2
\]
has absolute value at most the same quantity. Hence
\[
D(q)\geq D(p)-2(2B\varepsilon+\varepsilon^2)>0.
\]
\end{proof}

The estimate is simultaneous over the full error box and makes no distributional assumption. Separate error bounds can sharpen it by retaining the individual terms in the two expansions.

\section{Algorithms}
Given nodes and weights, the first certificate is computed in one pass: accumulate $p_1,p_2,p_3$, form $D=p_2^2-p_1p_3$, and certify a negative node when $D>0$. This costs $O(n)$ arithmetic operations and $O(1)$ auxiliary storage for $n$ nodes. With error data, report a robust certificate only if
\[
D-2(2B\varepsilon+\varepsilon^2)>0.
\]

At general level $m$, construct $H_m$ from $p_1,\ldots,p_{2m-1}$ and compute its smallest eigenvalue. Matrix construction costs $O(m^2)$ and dense symmetric eigendecomposition costs $O(m^3)$. If $\lambda_{\min}(H_m)<0$, a corresponding normalized eigenvector $c$ provides the polynomial witness $f_c$. By Rayleigh--Ritz,
\[
\min_{\|c\|_2=1}c^{\mathsf T}H_mc=\lambda_{\min}(H_m),
\]
so this is the strongest witness under Euclidean coefficient normalization.

\section{Random induced bipartite states}
A random pure state on
\[
\mathbb C^d\otimes\mathbb C^d\otimes\mathbb C^s
\]
produces an induced mixed state after the $s$-dimensional environment is traced out. In a scaling such as $s\sim\lambda d^2$, an asymptotic threshold analysis has three distinct tasks:
\begin{enumerate}[label=\arabic*.]
\item determine limiting partial-transpose moments;
\item prove concentration of empirical moments;
\item analyze the sign or least eigenvalue of the resulting shifted Hankel matrix.
\end{enumerate}
The results above provide the deterministic implication needed in the third task. Stability converts moment concentration into sign concentration whenever the limiting margin is nonzero. They do not, by themselves, prove existence, uniqueness, or values of random-state thresholds.

\section{Scope and boundary cases}
The sum-of-squares identity is algebraic and needs no sign assumptions. Nonnegative weights are essential for inferring node negativity from a violation: a negative weight could otherwise create a negative quadratic form despite nonnegative nodes. Zero-weight nodes are irrelevant, and zero nodes do not contribute to any shifted moment.

At level one the criterion is merely $p_1\geq0$. Level two introduces the first nonlinear determinant condition. For $m>2$, checking only the full determinant is insufficient; positive semidefiniteness requires all eigenvalues to be nonnegative.

Positive rescaling of every node preserves every violation. Indeed, $x_j\mapsto rx_j$ sends the level-two gap to
\[
(r^2p_2)^2-(rp_1)(r^3p_3)=r^4(p_2^2-p_1p_3),
\]
and at general level acts by positive diagonal congruence, up to a positive factor. Multiplying all weights by a common positive constant also preserves signs. Thus probability normalization and spectral units do not affect detection.

Numerically, an eigenvalue near zero should be treated as indeterminate unless a perturbation bound separates it from zero. The level-two stability theorem gives such a bound directly. At higher levels, an operator-norm bound $\eta$ on matrix error makes a computed eigenvalue below $-\eta$ a rigorous negative-eigenvalue certificate.

\section{Discussion}
The construction has three equivalent interpretations: a moment consistency test, a polynomial witness method, and a Gram geometry. Increasing $m$ enlarges the probe space without losing earlier witnesses. Nevertheless, bounded-degree polynomials may fail to isolate a small negative component; finite-level satisfaction is not equivalent to positivity.

Higher levels trade stronger detection for additional moment measurements and poorer numerical conditioning. Orthogonal-polynomial bases, spectral rescaling, and interval arithmetic are natural remedies. Statistical reporting should preserve the central asymmetry: a robust negative direction is decisive, while a positive finite matrix only records that the available probes found no contradiction.

\section{Future directions}
For fixed $m\geq2$, one may seek an exact constant $\lambda_m$ governing induced-state behavior under $s\sim\lambda d^2$. The limiting moments should determine a finite Hankel determinant or least eigenvalue whose sign changes at an algebraic critical point.

Nesting motivates the conjectures $\lambda_m<\lambda_{m+1}$ and convergence to the full PPT threshold. A proof would need to show that each new polynomial degree detects genuinely new negative support. If limiting determinants cross zero transversely and moments concentrate exponentially, deterministic stability may also yield quantitative finite-size transition windows.

Because the certificate is model-independent, universality beyond Gaussian or complex Wishart ensembles is another natural question. Finally, optimizing the polynomial under physically meaningful normalization leads to generalized eigenvalue problems, orthogonal polynomials, and Christoffel functions, with potential reductions in experimental sample complexity.

\section{Conclusion}
Finite spectra supported on $[0,\infty)$ generate positive semidefinite shifted Hankel matrices. The exact identity
\[
c^{\mathsf T}H_mc=\sum_jw_jx_jf_c(x_j)^2
\]
proves positivity, gives a Gram factorization, and turns negative eigenvectors into witnesses. The hierarchy is nested; its first nonlinear condition is $p_2^2\leq p_1p_3$; and a strict reverse inequality certifies a negative node. An explicit perturbation budget guarantees that a sufficiently separated violation survives bounded measurement error. These results form a self-contained deterministic basis for practical moment tests and future random-state threshold analysis.

\end{document}

