from typing import Sequence

def first_gap(weights: Sequence[float], nodes: Sequence[float]) -> float:
    if len(weights) != len(nodes):
        raise ValueError("dimension mismatch")
    p = [sum(w*x**k for w,x in zip(weights,nodes)) for k in (1,2,3)]
    return p[1]**2-p[0]*p[2]

examples=[([1.0,1.0,1.0],[1.0,2.0,3.0]),([1.0,1.0,1.0],[-1.0,2.0,3.0]),([0.01,1.0,1.0],[-0.01,1.0,2.0])]
for weights,xs in examples:
    gap=first_gap(weights,xs)
    print(xs, gap, "negative node certified" if gap>0 else "inconclusive")

